function buildAlliedFort(){if(selectedVehicle!=='engineer')return false;return buildFortFor(player())}
function buildFortFor(h,quiet=false){const tell=s=>{if(!quiet)toast(s)},clock=h===player()?time:h.age||0;if(h.dead)return false;if(h.building&&!h.building.dead&&h.building.progress<1){tell('推铲正在筑垒中');return false}const ahead=h.x+h.dir*160;let f=forts.find(f=>!f.dead&&f.allied&&Math.abs(f.x+f.rise-ahead)<180);if(f&&(f.layers||1)>=3){tell('这座堡垒已达到三层上限');return false}if(f&&f.progress<1){tell('这座堡垒正在施工');return false}if(h.energy<5){tell('筑垒需要 5 能量');return false}if(h.buildCooldown>clock){tell('推铲冷却中');return false}h.energy-=5;if(f){f.baseHeight=fortHeight(f);f.layers=(f.layers||1)+1;f.h=105*f.layers;f.progress=0;f.max+=130;f.hp=Math.min(f.max,f.hp+130)}else{f={x:h.dir>0?ahead-300:ahead-90,rise:h.dir>0?300:90,top:60,fall:h.dir>0?90:300,h:105,progress:0,layers:1,hp:260,max:260,dead:false,allied:true};forts.push(f)}h.building=f;h.buildCooldown=clock+12;h.buildAnim=0;tell(`推铲展开：正在构筑第 ${f.layers} 层堡垒 / 最多三层`);return true}

function drawArmoredCar(t){ctx.save();ctx.translate(t.x,t.y);ctx.rotate(t.angle||0);ctx.scale(t.turn||1,1);ctx.lineJoin='round';poly([[-51,7],[-49,-22],[-27,-36],[22,-35],[49,-16],[57,6]],t.allied?'#455d64':'#5d6249','#152528',3);poly([[-35,-22],[-21,-31],[17,-30],[34,-17],[12,-15]],'#7e9392');poly([[19,-28],[36,-15],[15,-16]],'#142b33');rect(-39,-11,65,15,t.allied?'#354d57':'#494f38');for(let j=0;j<3;j++)line(-34+j*10,-8,-34+j*10,1,'#728380',2);rect(42,-8,8,5,'#e5c85a');rect(-49,-10,5,5,'#db614e');for(const x of [-33,-6,32]){circle(x,10,14,'#111c22','#82918b');circle(x,10,8,'#53626a');ctx.save();ctx.translate(x,10);ctx.rotate(t.tread/12);for(let i=0;i<5;i++){ctx.rotate(Math.PI*2/5);line(3,0,10,0,'#91a6a4',2)}ctx.restore()}poly([[-8,-24],[1,-35],[20,-35],[30,-24]],'#2d4249','#728784',1);if(t.allied){rect(-14,-19,6,14,'#95d7c6');rect(-18,-15,14,6,'#95d7c6')}ctx.restore();const a=t.aimAngle??(t.dir<0?Math.PI:0);ctx.save();ctx.translate(t.x,t.y-23);ctx.rotate(a);rect(3,-4,53,8,'#253c43');rect(11,-3,44,3,'#8caaa7');rect(52,-6,9,12,'#435b63');circle(0,0,7,'#718a89');ctx.restore();if(t.hp<t.max){rect(t.x-30,t.y-49,60,3,'#192628');rect(t.x-30,t.y-49,60*t.hp/t.max,3,'#d7bb72')}}
function drawAlliedPlow(h){ctx.save();ctx.translate(h.x,h.y);ctx.rotate(h.angle);ctx.scale(h.turn,1);const extend=h.building&&h.building.progress<1?22:0;line(32,-10,56+extend,1,'#a6bac0',7);poly([[56+extend,-22],[64+extend,-24],[78+extend,23],[52+extend,18]],'#667c83','#b6c5ba',2);ctx.restore()}
function aimError(target){if(!isFlyingVehicle()&&target.allied&&save.tracks===3&&Math.random()<.28){const sign=Math.random()<.5?-1:1;return{x:sign*(18+Math.random()*16),y:sign*(18+Math.random()*20)}}return{x:0,y:0}}
function damageReduction(){return isFlyingVehicle()?1:[0,1,.85,.7][save.tracks]}
function damagedSmoke(h,dt){if(h.dead||h.hp>=(h.max||100)*.35)return;h.smokeClock=(h.smokeClock||0)-dt;if(h.smokeClock>0)return;h.smokeClock=.16;const x=h.x-18+(Math.random()-.5)*32,y=h.y-16;particles.push({x,y,vx:(Math.random()-.5)*12,vy:-16-Math.random()*9,life:.65+Math.random()*.4,max:1.1,size:5+Math.random()*6,smoke:true,alpha:.36,block:false});particles.push({x:x+(Math.random()-.5)*12,y:y-6,vx:(Math.random()-.5)*8,vy:-20,life:.7,max:.7,size:3+Math.random()*4,smoke:true,block:true,alpha:.45,rotation:Math.random()*3});if(Math.random()<.55)particles.push({x:x+8,y:y-3,vx:(Math.random()-.5)*18,vy:-30,life:.4,max:.4,size:1.6,smoke:false,ember:true})}

const VEHICLE_CARDS={heli:{title:'直升机',code:'D-72FE',desc:'空中机动 · 机枪 + 导弹',detail:'持续滑跑后自动起飞。100 耐久，机枪每 5 发耗 1 能量，导弹 25 能量。'},tank:{title:'重装坦克',code:'T-500',desc:'500 耐久 · 强化主炮',detail:'主炮伤害 45 / 65 / 90，移速 65 / 78 / 92。每发主炮耗能 2，升级增加火力、移速和防御。'},engineer:{title:'工程装甲车',code:'E-350',desc:'轮式装甲 · 三层筑垒',detail:'350 耐久。按 B 部署推铲构筑堡垒，同一处最多叠三层，每次耗能 5。主炮每发耗能 2。'}};
function openVehicleSelection(){choiceVehicle=selectedVehicle;openModal(`<div class="eyebrow">VEHICLE SELECTION / 载具整备</div><h2 class="selection-title">选择你的作战载具</h2><div class="selection-preview"><span id="previewCode"></span><canvas id="vehiclePreview" width="1000" height="340" aria-label="载具动态预览"></canvas></div><div class="vehicle-choices">${Object.entries(VEHICLE_CARDS).map(([key,v])=>`<button class="vehicle-choice" data-vehicle="${key}"><b>${v.title}</b><small>${v.desc}</small></button>`).join('')}</div><p class="vehicle-detail" id="vehicleDetail"></p><button class="primary select-deploy" id="deployVehicle">确认载具 · 开始行动 <b>↗</b></button>`);document.querySelectorAll('[data-vehicle]').forEach(b=>b.onclick=()=>{choiceVehicle=b.dataset.vehicle;refreshVehicleSelection()});$('deployVehicle').onclick=()=>start(choiceVehicle);refreshVehicleSelection()}
function refreshVehicleSelection(){document.querySelectorAll('[data-vehicle]').forEach(b=>{const active=b.dataset.vehicle===choiceVehicle;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});$('previewCode').textContent=VEHICLE_CARDS[choiceVehicle].code+' / SYSTEM READY';$('vehicleDetail').textContent=VEHICLE_CARDS[choiceVehicle].detail}
function renderSelectionPreview(){if($('modal').hidden)return;const c=$('vehiclePreview');if(!c)return;const pctx=c.getContext('2d'),mainCtx=ctx;pctx.clearRect(0,0,c.width,c.height);pctx.save();pctx.fillStyle='#62736850';pctx.fillRect(0,285,c.width,2);for(let i=0;i<17;i++){pctx.fillStyle='#c7b96a30';pctx.fillRect((i*80-time*28)%1100,300,30,3)}
 try{ctx=pctx;if(choiceVehicle==='fighter'){drawFighter({...heli,x:500,y:210,angle:-.02,gear:.9,flip:1,vx:200},1.7,true)}else if(choiceVehicle==='factory'){drawFactory({x:500,y:230,angle:0,turn:1,tread:time*40},2.5)}else if(choiceVehicle==='drone'){drawDrone({...newDrone(500,false),x:500,y:205,aimAngle:Math.sin(time)*.2},3.8,true)}else if(choiceVehicle==='heli')drawHeli(540,205+Math.sin(time*2)*3,1.65,-.03,1,1,true);else{const demo={x:500,y:220,angle:0,turn:1,dir:1,tread:time*65,hp:500,max:500,level:save.tracks,allied:true,aimAngle:-.12+Math.sin(time*.8)*.08,vehicle:choiceVehicle};ctx.translate(500,210);ctx.scale(2.4,2.4);ctx.translate(-500,-210);if(choiceVehicle==='engineer'){drawArmoredCar(demo);drawAlliedPlow(demo)}else drawTank(demo)}}finally{ctx=mainCtx;pctx.restore()}}

function newDrone(x,enemy=false){return{x,y:groundAt(x)-135,vx:0,vy:0,hp:enemy?65:35,max:enemy?65:35,energy:100,dir:1,angle:0,rotor:0,aimAngle:0,drone:true,enemy,allied:!enemy,grounded:false,dead:false,shotCredit:0,hit:0,cd:1}}
function stepDrone(d,ax,ay,dt){d.energy=Math.min(100,d.energy+dt);d.hit=Math.max(0,d.hit-dt);d.vx=clamp((d.vx+ax*750*dt)*Math.exp(-dt*1.5),-440,440);d.vy=clamp((d.vy+ay*650*dt)*Math.exp(-dt*1.8),-300,300);d.x=clamp(d.x+d.vx*dt,80,WORLD-80);const foot=d.role==='suicide'?16:22;d.y=clamp(d.y+d.vy*dt,55,groundAt(d.x)-foot);d.grounded=d.y>=groundAt(d.x)-foot-.1;d.angle=mix(d.angle,clamp(d.vx*.00035,-.15,.15),dt*5);d.rotor+=dt*65;if(Math.abs(d.vx)>10)d.dir=Math.sign(d.vx)}
function droneAim(d,tx,ty){const pivot={x:d.x,y:d.y+7},a=Math.atan2(ty-pivot.y,tx-pivot.x);return{x:pivot.x+Math.cos(a)*25,y:pivot.y+Math.sin(a)*25,a,dx:Math.cos(a),dy:Math.sin(a),pivot}}
function drawDrone(d,scale=1,preview=false){ctx.save();ctx.translate(d.x,d.y);ctx.scale(scale,scale);ctx.rotate(d.angle||0);line(-27,-8,27,-8,'#5f757d',5);line(-19,-8,0,7,'#263b43',5);line(19,-8,0,7,'#263b43',5);for(const x of [-28,28]){circle(x,-9,11,'#15232b','#6b8389');ctx.save();ctx.translate(x,-9);ctx.rotate(preview?time*65:d.rotor);line(-13,0,13,0,d.enemy?'#ea5c4c':'#e5c75e',3);ctx.restore()}poly([[-17,-7],[-9,-14],[13,-13],[21,-3],[14,10],[-13,10]],d.enemy?'#713e39':'#465c67','#14252c',2);rect(-8,-9,11,5,d.enemy?'#ff8066':'#a1c7cb');circle(16,1,3,d.enemy?'#ff6554':'#e7e687');ctx.restore();ctx.save();ctx.translate(d.x,d.y+7);ctx.scale(scale,scale);ctx.rotate(d.aimAngle||0);rect(1,-3,24,6,'#93a6a4');rect(20,-4,5,8,d.enemy?'#ee7762':'#dcd279');ctx.restore()}
function drawDroneLaser(d,color){const a={x:d.x+Math.cos(d.aimAngle)*25,y:d.y+7+Math.sin(d.aimAngle)*25};ctx.save();ctx.setLineDash([4,9]);ctx.globalAlpha=.35;line(a.x,a.y,a.x+Math.cos(d.aimAngle)*700,a.y+Math.sin(d.aimAngle)*700,color,1);ctx.restore()}
function drawUnitBars(e,offset){const y=e.y-offset;rect(e.x-23,y,46,3,'#282222');rect(e.x-23,y,46*e.hp/e.max,3,'#ea5e50');rect(e.x-23,y+6,46*e.energy/100,2,'#e3c962');ctx.fillStyle='#e9dcc5';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText(Number(e.hp.toFixed(1)),e.x,y-4);ctx.textAlign='left'}
function bodyBox(v){if(v.drone)return{rx:31,ry:16,mass:1,air:true};if(v===heli||v.enemy)return{rx:83,ry:35,mass:4,air:!v.grounded};return{rx:44,ry:25,mass:v.stage==='engineer'||v.phase||selectedVehicle==='engineer'&&v===playerTank?7:10,air:false}}
function separateVehicles(a,b,dt){const aa=bodyBox(a),bb=bodyBox(b),dx=b.x-a.x,dy=b.y-a.y,ox=aa.rx+bb.rx-Math.abs(dx),oy=aa.ry+bb.ry-Math.abs(dy);if(ox<=0||oy<=0)return false;const vertical=(aa.air&&bb.air&&oy<ox*.7),sign=vertical?(dy<0?-1:1):(dx===0?(a.dir||1):Math.sign(dx)),overlap=vertical?oy:ox,wa=bb.mass/(aa.mass+bb.mass),wb=aa.mass/(aa.mass+bb.mass),push=overlap+.2;
 if(vertical){a.y-=sign*push*wa;b.y+=sign*push*wb;a.vy-=sign*25*wa;b.vy+=sign*25*wb}else{a.x=clamp(a.x-sign*push*wa,80,WORLD-80);b.x=clamp(b.x+sign*push*wb,80,WORLD-80);const relative=Math.abs((a.vx||0)-(b.vx||0)),impulse=Math.min(110,25+relative*.45);a.vx-=sign*impulse*wa;b.vx+=sign*impulse*wb}
 for(const [v,box] of [[a,aa],[b,bb]]){if(box.air)v.y=Math.min(v.y,groundAt(v.x)-(v.drone?22:helicopterFootOffset(v)+1));else v.y=groundAt(v.x)-(v.fighter?41:v===heli||v.enemy||v.kind==='heli'?70:23);if(v.enemy&&!v.drone){v.evade=2.5;v.cd=Math.max(v.cd,1.2)}}return true}
function resolveVehicleContacts(dt){const all=[...friendlyTargets(),...enemies()];for(let i=0;i<all.length;i++)for(let j=i+1;j<all.length;j++)if(!all[i].dead&&!all[j].dead)separateVehicles(all[i],all[j],dt)}
VEHICLE_CARDS.drone={title:'轻型无人机',code:'U-35',desc:'35 耐久 · 轻型飞行',detail:'无需助跑，WASD 自由飞行。每发伤害 5，射击间隔 0.3 秒，每发消耗 3 能量；配有枪口雷射。'};

function vehicleDisplayName(){return VEHICLE_CARDS[selectedVehicle]?.title||'载具'}

function updateEnemyMissiles(e,target,dt,attacking){e.missileCd=Math.max(0,(e.missileCd||0)-dt);if(e.dead||e.grounded||e.landing){e.missileWindup=0;e.missileTarget=null;return}if(e.missileWindup>0){e.missileWindup-=dt;if(e.missileWindup<=0){if(e.energy>=25){const p=e.missileTarget,a=Math.atan2(p.y-e.y,p.x-e.x);e.energy-=25;e.missileCd=10;missiles.push({x:e.x+e.dir*65,y:e.y+15,vx:Math.cos(a)*220,vy:Math.sin(a)*220,tx:p.x,ty:p.y,lock:null,life:12,level:clamp(e.missileLevel||e.level||1,1,3),enemy:true,homing:true,owner:e});battleAudio.play('missile',{x:e.x,y:e.y})}e.missileTarget=null}return}if(e.missileCd===0&&e.energy>=25&&Math.hypot(target.x-e.x,target.y-e.y)<1100){e.missileWindup=.8;e.missileTarget={x:target.x,y:target.y};toast('敌方直升机正在瞄准导弹 · 注意躲避')}}
function drawEnemyMissileWarning(e){if(!e.missileTarget||e.missileWindup<=0)return;const p=e.missileTarget;ctx.save();ctx.globalAlpha=.65;ctx.setLineDash([7,9]);line(e.x,e.y,p.x,p.y,'#ef9e63',1.3);ctx.setLineDash([]);circle(p.x,p.y,14+Math.sin(time*12)*2,null,'#f4ae70');line(p.x-20,p.y,p.x+20,p.y,'#f4ae70');line(p.x,p.y-20,p.x,p.y+20,'#f4ae70');ctx.restore()}

function helicopterFootOffset(h){return 40+30*clamp(h.gear??1,0,1)+Math.abs(Math.sin(h.angle||0))*55}
function applyFlightCollisionDamage(h,damage,enemy=false){if(damage<=0||h.collisionGrace>0||h.collisionCooldown>0||h.dead)return;h.collisionCooldown=.6;if(enemy)damageEnemy(h,Math.min(35,damage));else hurt(Math.min(35,damage))}
function helicopterHull(h){const angle=h.angle||0,flip=Math.abs(h.flip||1)>.3?Math.sign(h.flip||1):h.dir||1,c=Math.cos(angle),s=Math.sin(angle);return[[-86,-22],[0,-44],[82,-24],[160,22],[80,31],[-65,20]].map(([x,y])=>({x:h.x+x*flip*c-y*s,y:h.y+x*flip*s+y*c}))}
function hullBuildingContact(h,b){const hull=helicopterHull(h),left=b.x+6,right=b.x+b.w-6,top=GROUND-b.h+16,bottom=GROUND;if(right<=left||top>=bottom)return null;const rect=[{x:left,y:top},{x:right,y:top},{x:right,y:bottom},{x:left,y:bottom}],axes=[{x:1,y:0},{x:0,y:1}];for(let i=0;i<hull.length;i++){const a=hull[i],z=hull[(i+1)%hull.length],len=Math.hypot(z.x-a.x,z.y-a.y);axes.push({x:-(z.y-a.y)/len,y:(z.x-a.x)/len})}let best=null;const hx=hull.reduce((s,p)=>s+p.x,0)/hull.length,hy=hull.reduce((s,p)=>s+p.y,0)/hull.length;
 for(const axis of axes){const hp=hull.map(p=>p.x*axis.x+p.y*axis.y),bp=rect.map(p=>p.x*axis.x+p.y*axis.y),minH=Math.min(...hp),maxH=Math.max(...hp),minB=Math.min(...bp),maxB=Math.max(...bp);if(maxH<=minB||maxB<=minH)return null;const toward=(hx-(left+right)/2)*axis.x+(hy-(top+bottom)/2)*axis.y>=0?1:-1,depth=toward>0?maxB-minH:maxH-minB;if(!best||depth<best.depth)best={nx:axis.x*toward,ny:axis.y*toward,depth}}return best}
function resolveHelicopterBuildings(h,enemy=false){for(const b of buildings){if(b.x+b.w<h.x-210||b.x>h.x+210)continue;const contact=hullBuildingContact(h,b);if(!contact)continue;const {nx,ny,depth}=contact,closing=Math.max(0,-(h.vx*nx+h.vy*ny));h.x=clamp(h.x+nx*(depth+1),100,WORLD-100);h.y+=ny*(depth+1);const normalV=h.vx*nx+h.vy*ny;if(normalV<0){h.vx-=normalV*nx*1.15;h.vy-=normalV*ny*1.15}const damage=Math.min(25,Math.max(0,closing-35)*.12);applyFlightCollisionDamage(h,damage,enemy);if(damage>0)impactEffect(h.x-nx*35,h.y-ny*20,false);break}}

function missileAimPoint(m){if(m.enemy){const t=typeof combatTarget==='function'?combatTarget(m.owner):player();return{x:t.x,y:t.y}};const p=screenToWorld(pointer.x,pointer.y);return{x:clamp(p.x,0,WORLD),y:clamp(p.y,MISSILE_CEILING,GROUND)}}
function missileContact(m,x0,y0,x1,y1){let best=null;const set=(t,kind,target=null)=>{if(t>=0&&t<=1&&(!best||t<best.t))best={t,kind,target,x:mix(x0,x1,t),y:mix(y0,y1,t)}};const length=Math.hypot(x1-x0,y1-y0),steps=Math.max(1,Math.ceil(length/5));
 for(let i=0;i<=steps;i++){const t=i/steps,x=mix(x0,x1,t),y=mix(y0,y1,t);if(x<=0||x>=WORLD||y<=MISSILE_CEILING){set(t,'boundary');break}if(y>=groundAt(x)){set(t,'terrain');break}}
 for(const b of buildings){if(b.x+b.w<Math.min(x0,x1)||b.x>Math.max(x0,x1))continue;const left=b.x+6,right=b.x+b.w-6,top=GROUND-b.h+16;if(right<=left)continue;const t=segmentEntryTime(x0,y0,x1,y1,left,top,right-left,GROUND-top);if(t!==null)set(t,'building',b)}
 if(typeof missionMissileContact==='function'){const c=missionMissileContact(m,x0,y0,x1,y1);if(c)set(c.t,'objective',c.target)}for(const v of [...friendlyTargets(),...enemies()]){if(v.dead||v===m.owner||(m.enemy?!friendlyTargets().includes(v):friendlyTargets().includes(v)))continue;const box=bodyBox(v),t=segmentEntryTime(x0,y0,x1,y1,v.x-box.rx,v.y-box.ry,box.rx*2,box.ry*2);if(t!==null)set(t,'vehicle',v)}return best}
function segmentEntryTime(x0,y0,x1,y1,x,y,w,h){let low=0,high=1,dx=x1-x0,dy=y1-y0;for(const[p,q]of[[-dx,x0-x],[dx,x+w-x0],[-dy,y0-y],[dy,y+h-y0]]){if(p===0){if(q<0)return null}else{const r=q/p;if(p<0)low=Math.max(low,r);else high=Math.min(high,r);if(low>high)return null}}return low}
function updateGuidedMissiles(dt){for(const m of missiles){m.life-=dt;if(m.life<=0){m.life=0;continue}const target=missileAimPoint(m);m.tx=target.x;m.ty=target.y;let angle=Math.atan2(m.vy,m.vx),dx=m.tx-m.x,dy=m.ty-m.y;if(Math.hypot(dx,dy)>24){const desired=Math.atan2(dy,dx),turn=Math.atan2(Math.sin(desired-angle),Math.cos(desired-angle)),limit=(m.level===3?4.2:3.1)*dt;angle+=clamp(turn,-limit,limit)}const speed=Math.min(600,Math.hypot(m.vx,m.vy)+dt*250),oldX=m.x,oldY=m.y;m.vx=Math.cos(angle)*speed;m.vy=Math.sin(angle)*speed;const nx=m.x+m.vx*dt,ny=m.y+m.vy*dt,contact=missileContact(m,oldX,oldY,nx,ny);m.x=contact?contact.x:nx;m.y=contact?contact.y:ny;particles.push({x:m.x,y:m.y,vx:-m.vx*.05,vy:10,life:.35+m.level*.1,max:.7,size:3+m.level,smoke:m.level<3});if(contact){m.hitKind=contact.kind;detonateMissile(m);m.life=0}}missiles=missiles.filter(m=>m.life>0)}
